import argparse
import json
import os
import re

import yaml
from openai import OpenAI

# Default model
DEFAULT_MODEL = "gpt-5"

# Output mapping for TypeScript coverage
# Keyed by (api_name, category_name) -> (subdir under promptfoo, filename)
# These map to coverage test files in dev-mcp that correspond to coverage tests
# generated from shopify-dev source data.
TS_OUTPUT_MAP = {
    # App Home
    ("app_home", "Polaris web components"): (
        "polaris",
        "app_home_polaris_web_components_tests.yaml",
    ),
    # NOTE: app_home + "Patterns" removed - app_home_patterns_tests_with_urls.yaml
    # has 12 custom assertions checking fetch_full_docs calls and should not be regenerated
    # Admin Extensions (both prefixes exist)
    ("admin_extensions", "Components"): (
        "polaris",
        "admin_extensions_components_tests.yaml",
    ),
    ("polaris_admin_extensions", "Polaris web components"): (
        "polaris",
        "polaris_admin_extensions_polaris_web_components_tests.yaml",
    ),
    # Checkout Extensions
    ("checkout_extensions", "Components"): (
        "polaris",
        "checkout_extensions_components_tests.yaml",
    ),
    ("polaris_checkout_extensions", "Polaris web components"): (
        "polaris",
        "polaris_checkout_extensions_polaris_web_components_tests.yaml",
    ),
    # Customer Account Extensions
    ("customer_account_extensions", "components"): (
        "polaris",
        "customer_account_extensions_components_tests.yaml",
    ),
    ("polaris_customer_account_extensions", "Polaris web components"): (
        "polaris",
        "polaris_customer_account_extensions_polaris_web_components_tests.yaml",
    ),
    # POS UI Extensions
    ("pos_ui", "Components"): (
        "polaris",
        "pos_ui_components_tests.yaml",
    ),
    ("polaris_pos_ui_extensions", "Polaris web components"): (
        "polaris",
        "polaris_pos_ui_extensions_polaris_web_components_tests.yaml",
    ),
    # Storefront and Hydrogen
    ("storefront_web_components", "components"): (
        ".",
        "storefront-web-components.yaml",
    ),
    ("hydrogen", "components"): (
        ".",
        "hydrogen.yaml",
    ),
}


def load_api_config():
    current_dir = os.path.dirname(os.path.abspath(__file__))
    config_path = os.path.join(current_dir, "api_config.json")

    with open(config_path, "r") as file:
        return json.load(file)


def generate_yaml_file(actions, api_name, category_name, one_to_one_tags=None, promptfoo_dir=None):
    yaml_list = []

    for action in actions:
        vars_dict = {
            "prompt": action["action"],
        }

        if one_to_one_tags and action["operation_name"] in one_to_one_tags:
            tag = one_to_one_tags[action["operation_name"]]
            tag_name = tag.strip("<>/ ")
            escaped_tag = re.escape(tag_name)
            pattern = rf"(<{escaped_tag}|(?:root\.)?createComponent\({escaped_tag})"
            vars_dict["matches"] = pattern

        entry = {
            "description": f"{api_name.lower()} {category_name.lower()}",
            "vars": vars_dict,
        }
        yaml_list.append(entry)

    # Resolve output file based on mapping
    key = (api_name, category_name)
    if key not in TS_OUTPUT_MAP:
        raise ValueError(
            f"No output mapping configured for API '{api_name}' and category '{category_name}'"
        )
    subdir, out_name = TS_OUTPUT_MAP[key]

    if promptfoo_dir is None:
        promptfoo_dir = os.path.normpath(
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
        )

    output_dir = os.path.join(promptfoo_dir, subdir)
    os.makedirs(output_dir, exist_ok=True)
    filename = os.path.join(output_dir, out_name)
    
    # Check if target is a wrapper config (dict) or pure test file (list)
    if os.path.exists(filename):
        with open(filename, "r") as f:
            file_content = f.read()
            
        try:
            existing_data = yaml.safe_load(file_content)
            if isinstance(existing_data, dict) and "tests" in existing_data:
                # Check if tests uses file references (list of strings)
                if isinstance(existing_data["tests"], list) and existing_data["tests"]:
                    if isinstance(existing_data["tests"][0], str):
                        # File references - don't touch this file
                        print(f"⚠️  Skipping {filename} - uses external file references")
                        print(f"   Current: {existing_data['tests']}")
                        print(f"   To regenerate, update mapping to point to the referenced file")
                        return filename
                
                # Wrapper config with inline tests - text-based replacement to preserve formatting
                print(f"Updating wrapper config: preserving prompts/providers/assertions")
                
                # Find the "tests:" line and replace everything after it
                lines = file_content.split('\n')
                tests_line_idx = None
                for i, line in enumerate(lines):
                    if line.strip() == 'tests:' or line.startswith('tests:'):
                        tests_line_idx = i
                        break
                
                if tests_line_idx is not None:
                    # Keep everything up to and including "tests:" line
                    new_content = '\n'.join(lines[:tests_line_idx + 1]) + '\n'
                    
                    # Add new tests with proper indentation (each test indented 2 spaces)
                    test_yaml = yaml.dump(yaml_list, default_flow_style=False, sort_keys=False)
                    # Indent each line by 2 spaces (for tests: array items)
                    indented_tests = '\n'.join('  ' + line if line else line for line in test_yaml.split('\n'))
                    new_content += indented_tests
                    
                    with open(filename, "w") as out:
                        out.write(new_content)
                    print(f"Updated {filename} with {len(yaml_list)} test cases (preserved wrapper)")
                    return filename
        except:
            pass  # Fall through to overwrite
    
    # Pure test file or doesn't exist - write directly
    with open(filename, "w") as file:
        yaml.dump(yaml_list, file, default_flow_style=False, sort_keys=False)

    return filename


def fetch_gpt4_turbo_actions(operation_name, description, properties, prompt_config):
    # Create OpenAI client  
    client = OpenAI(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_API_BASE_URL")
    )

    prompt_text = (
        f"{prompt_config['intro']}\n\nOperation Description: {description}\n\n"
    )

    if properties:
        prompt_text += "Available Properties and Capabilities:\n"
        for prop in properties[:10]:
            prop_desc = (
                prop["description"][:200] + "..."
                if len(prop["description"]) > 200
                else prop["description"]
            )
            prompt_text += f"- {prop['name']}: {prop_desc}\n"
            if prop["value"] and len(prop["value"]) < 100:
                prompt_text += f"  Possible values: {prop['value']}\n"
        prompt_text += "\n"

    prompt_text += f"Context: {prompt_config['context']}\n\nIMPORTANT RULES:\n"

    for rule in prompt_config["rules"]:
        prompt_text += f"- {rule.format(operation_name=operation_name)}\n"

    prompt_text += "\nGood examples of prompts:\n"
    for example in prompt_config["examples"]:
        prompt_text += f"- '{example}'\n"

    prompt_text += "\nGenerate ONE realistic prompt for this operation based on its description and available properties/capabilities:"

    completion_args = {
        "model": DEFAULT_MODEL,
        "messages": [{"role": "user", "content": prompt_text}],
    }
    
    if not DEFAULT_MODEL.startswith("gpt-5"):
        completion_args["temperature"] = 0.1
    
    response = client.chat.completions.create(**completion_args)

    return response.choices[0].message.content.strip()


def extract_operations_by_category(json_file_path, category):
    with open(json_file_path, "r") as file:
        data = json.load(file)

    operations = []

    for item in data:
        if item.get("category") == category:
            operation_name = item.get("name", "")
            description = item.get("description", "")

            properties = []
            definitions = item.get("definitions", [])

            if definitions:
                properties_def = None
                for definition in definitions:
                    if definition.get("title", "").lower() == "properties":
                        properties_def = definition
                        break

                if properties_def:
                    type_name = properties_def.get("type", "")
                    type_definitions = properties_def.get("typeDefinitions", {})

                    if type_name and type_name in type_definitions:
                        members = type_definitions[type_name].get("members", [])

                        for member in members:
                            if member.get("isPrivate") or member.get("name", "").endswith("Callback"):
                                continue

                            prop_name = member.get("name", "")
                            prop_description = member.get("description", "")
                            prop_value = member.get("value", "")

                            if prop_name and prop_description:
                                properties.append(
                                    {
                                        "name": prop_name,
                                        "description": prop_description,
                                        "value": prop_value,
                                    }
                                )

            operations.append(
                {
                    "name": operation_name,
                    "description": description,
                    "properties": properties,
                }
            )

    return operations


def generate_actions(operations, prompt_config):
    actions = []

    for operation in operations:
        action = fetch_gpt4_turbo_actions(
            operation["name"],
            operation["description"],
            operation["properties"],
            prompt_config,
        )
        print(f"Action for operation {operation['name']}: {action}")
        actions.append({"operation_name": operation["name"], "action": action})

    return actions


def fetch_tags(json_file_path, category):
    with open(json_file_path, "r") as file:
        data = json.load(file)

    tags_dict = {}

    for item in data:
        item_category = item.get("category", "")
        if category and item_category != category:
            continue

        operation_name = item.get("name", "")
        if not operation_name:
            continue

        default_example = item.get("defaultExample", {})
        if not default_example:
            continue

        codeblock = default_example.get("codeblock", {})
        if not codeblock:
            continue

        tabs = codeblock.get("tabs", [])
        if not tabs:
            continue

        tags_set = set()

        common_html_tags = {
            "html",
            "head",
            "body",
            "div",
            "span",
            "p",
            "a",
            "img",
            "ul",
            "ol",
            "li",
            "h1",
            "h2",
            "h3",
            "h4",
            "h5",
            "h6",
            "table",
            "tr",
            "td",
            "th",
            "form",
            "input",
            "button",
            "script",
            "style",
            "meta",
            "link",
            "title",
            "br",
            "hr",
            "nav",
            "header",
            "footer",
            "main",
            "section",
            "article",
            "aside",
            "s",
            "strong",
            "em",
            "i",
            "b",
            "u",
            "code",
            "pre",
            "blockquote",
            "cite",
        }

        for tab in tabs:
            code = tab.get("code", "")
            if not code:
                continue

            entity_self_closing = re.findall(
                r"&lt;([A-Za-z][A-Za-z0-9.\-]*)(?:[^&]|&(?!gt;))*?/&gt;",
                code,
                re.DOTALL,
            )
            entity_opening = re.findall(
                r"&lt;([A-Za-z][A-Za-z0-9.\-]*)(?:[^&]|&(?!gt;))*?&gt;", code, re.DOTALL
            )

            for component_name in entity_self_closing:
                if component_name.lower() not in common_html_tags:
                    tags_set.add(f"<{component_name} />")

            for component_name in entity_opening:
                if component_name.lower() not in common_html_tags:
                    if f"&lt;{component_name}" in code:
                        tag_content = code.split(f"&lt;{component_name}")[1].split(
                            "&gt;"
                        )[0]
                        if not tag_content.endswith("/"):
                            tags_set.add(f"<{component_name}>")

            regular_self_closing = re.findall(
                r"<([A-Za-z][A-Za-z0-9.\-]*)[^>]*?/>", code, re.DOTALL
            )
            regular_opening = re.findall(
                r"<([A-Za-z][A-Za-z0-9.\-]*)[^>]*?>", code, re.DOTALL
            )

            for component_name in regular_self_closing:
                if component_name.lower() not in common_html_tags:
                    tags_set.add(f"<{component_name} />")

            for component_name in regular_opening:
                if component_name.lower() not in common_html_tags:
                    if f"<{component_name}" in code:
                        tag_content = code.split(f"<{component_name}")[1].split(">")[0]
                        if not tag_content.endswith("/"):
                            tags_set.add(f"<{component_name}>")

        if tags_set:
            tags_dict[operation_name] = sorted(list(tags_set))

    print(f"Number of operations: {len(tags_dict)}")
    print("\n\nTags found for each operation:")
    print(json.dumps(tags_dict, indent=2))

    return tags_dict


def one_to_one_tags_dict(tags_dict):
    result = {}

    for key, tags in tags_dict.items():
        if not tags:
            continue

        best_tag = None
        best_score = float("-inf")

        key_lower = key.lower()

        for tag in tags:
            tag_name = tag.strip("<>/ ").lower()
            score = 0

            key_idx = 0
            tag_idx = 0

            while tag_idx < len(tag_name):
                if key_idx < len(key_lower) and tag_name[tag_idx] == key_lower[key_idx]:
                    score += 1
                    key_idx += 1
                else:
                    score -= 1
                tag_idx += 1

            while key_idx < len(key_lower):
                score -= 1
                key_idx += 1

            if score > best_score:
                best_score = score
                best_tag = tag

        if best_tag:
            result[key] = best_tag

    print("\n\nOne-to-one tags dict:")
    print(json.dumps(result, indent=2))

    return result


def main():
    parser = argparse.ArgumentParser(
        description="Generate TypeScript coverage test cases for different APIs and categories"
    )
    parser.add_argument(
        "--api", required=True, help="API name (e.g., 'app_home', 'admin_extensions')"
    )
    parser.add_argument(
        "--category",
        required=True,
        help="Category name (e.g., 'Polaris web components')",
    )
    parser.add_argument(
        "--version",
        type=str,
        required=True,
        help="The API version to use (e.g., 2025-10, 2025-07)",
    )

    args = parser.parse_args()

    api_name = args.api
    category_name = args.category
    version = args.version
    shopify_dev_root = os.getenv(
        "SHOPIFY_DEV_ROOT", os.path.expanduser("~/src/github.com/Shopify/shopify-dev")
    )

    api_config_dict = load_api_config()

    if api_name not in api_config_dict:
        print(f"Error: API '{api_name}' not found in configuration.")
        print(f"Available APIs: {list(api_config_dict.keys())}")
        return

    if not os.path.isdir(shopify_dev_root):
        print(
            f"Error: Could not find shopify-dev repository at '{shopify_dev_root}'.\n"
            "Set SHOPIFY_DEV_ROOT or clone to ~/src/github.com/Shopify/shopify-dev."
        )
        return

    api_config = api_config_dict[api_name]

    if category_name not in api_config["prompt_instructions"]:
        print(f"Error: Category '{category_name}' not found for API '{api_name}'.")
        print(
            f"Available categories for {api_name}: {list(api_config['prompt_instructions'].keys())}"
        )
        return

    # Substitute version in json_file path if it contains {version}
    json_file = api_config["json_file"]
    if "{version}" in json_file:
        json_file = json_file.format(version=version)
    
    json_path = os.path.join(shopify_dev_root, json_file)
    
    if not os.path.exists(json_path):
        print(f"Error: Data file not found at {json_path}")
        print(f"Make sure version '{version}' exists for API '{api_name}'")
        return

    operations = extract_operations_by_category(json_path, category_name)
    print(f"Found {len(operations)} {category_name} operations in {api_name}")

    if not operations:
        print(f"No operations found for category '{category_name}' in API '{api_name}'")
        return

    prompt_config = api_config["prompt_instructions"][category_name]

    tags = fetch_tags(json_path, category_name)
    one_to_one_tags = one_to_one_tags_dict(tags)

    actions = generate_actions(operations, prompt_config)

    # Resolve promptfoo directory and write to mapped output file
    promptfoo_dir = os.path.normpath(
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
    )
    filename = generate_yaml_file(
        actions, api_name, category_name, one_to_one_tags, promptfoo_dir
    )
    print(f"Generated coverage tests for {len(actions)} operations in: {filename}")


if __name__ == "__main__":
    main()


